import React, { useState } from 'react'
import axios from 'axios'

const API_URL = process.env.REACT_APP_API_URL || '/api'

const BG_IMAGE = ''
const LOGO_IMAGE = ''

const Login: React.FC = () => {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError('')
    try {
      const response = await axios.post(`${API_URL}/auth/login`, { username, password })
      localStorage.setItem('token', response.data.token)
      window.location.href = '/mdm/'
    } catch {
      setError('Credenciales incorrectas')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div
      className="min-h-screen flex items-center justify-center p-4"
      style={{
        backgroundImage: `url(data:image/webp;base64,${BG_IMAGE})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
      }}
    >
      <div className="relative z-10 w-full max-w-sm">
        <div style={{
          backgroundColor: 'rgba(5, 15, 5, 0.82)',
          border: '1px solid rgba(100,200,100,0.2)',
          borderRadius: 14,
          padding: '40px 36px',
          backdropFilter: 'blur(10px)',
        }}>
          {/* Logo Palmas */}
          <div className="flex justify-center mb-6">
            <img
              src={`data:image/webp;base64,${LOGO_IMAGE}`}
              alt="Grupo Palmas"
              style={{ height: 64, objectFit: 'contain', filter: 'brightness(0) invert(1)' }}
            />
          </div>

          <div style={{ textAlign: 'center', marginBottom: 28 }}>
            <div style={{ color: '#81c784', fontSize: 11, letterSpacing: 3, textTransform: 'uppercase', marginBottom: 4 }}>
              TI TULUMAYO · MDM PLATFORM
            </div>
          </div>

          <form onSubmit={handleLogin}>
            <div style={{ marginBottom: 16 }}>
              <label style={{ color: '#a5d6a7', fontSize: 12, display: 'block', marginBottom: 6 }}>USUARIO</label>
              <input
                type="text"
                value={username}
                onChange={e => setUsername(e.target.value)}
                placeholder="admin"
                required
                style={{
                  width: '100%', boxSizing: 'border-box',
                  backgroundColor: 'rgba(255,255,255,0.07)',
                  border: '1px solid rgba(100,200,100,0.3)',
                  borderRadius: 6, padding: '10px 14px',
                  color: 'white', fontSize: 14, outline: 'none',
                }}
              />
            </div>
            <div style={{ marginBottom: 20 }}>
              <label style={{ color: '#a5d6a7', fontSize: 12, display: 'block', marginBottom: 6 }}>CONTRASEÑA</label>
              <input
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="••••••••"
                required
                style={{
                  width: '100%', boxSizing: 'border-box',
                  backgroundColor: 'rgba(255,255,255,0.07)',
                  border: '1px solid rgba(100,200,100,0.3)',
                  borderRadius: 6, padding: '10px 14px',
                  color: 'white', fontSize: 14, outline: 'none',
                }}
              />
            </div>

            {error && (
              <div style={{ color: '#ef9a9a', fontSize: 13, marginBottom: 14, textAlign: 'center' }}>{error}</div>
            )}

            <button
              type="submit"
              disabled={loading}
              style={{
                width: '100%',
                backgroundColor: loading ? '#388e3c99' : '#2e7d32',
                color: 'white', fontWeight: 700, fontSize: 14,
                letterSpacing: 2, border: 'none', borderRadius: 6,
                padding: '12px', cursor: loading ? 'not-allowed' : 'pointer',
                textTransform: 'uppercase', transition: 'background 0.2s',
              }}
            >
              {loading ? 'INGRESANDO...' : 'INGRESAR'}
            </button>
          </form>
        </div>
        <div style={{ color: 'rgba(255,255,255,0.4)', fontSize: 11, textAlign: 'center', marginTop: 16 }}>
          Grupo Palmas MDM v1.0 — TI Corporativo
        </div>
      </div>
    </div>
  )
}

export default Login
